SELECT product, 1.0 * SUM(reordered) / COUNT(*) AS reorder_rate
FROM orders
GROUP BY product;

WITH totals AS (
  SELECT customer, SUM(amount) AS total
  FROM orders
  GROUP BY customer
), ranked AS (
  SELECT customer, total,
    DENSE_RANK() OVER (ORDER BY total DESC) AS place
  FROM totals
)
SELECT customer, total, place FROM ranked WHERE place = 1;
